import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { ubicacionesData } from "../data/ubicacionesData";

export default function Fusion() {
  const navigate = useNavigate();
  const chatEndRef = useRef(null);

  const [messages, setMessages] = useState([
    { type: "bot", content: "Bienvenido a TalkinPon. ¿Qué te gustaría consultar?" },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMoreOptions, setShowMoreOptions] = useState(false);
  const [showMap, setShowMap] = useState(false);
  const [animateMap, setAnimateMap] = useState(false);

  // ================== Opciones administrativas ==================
  const predefinedOptions = [
    { img: "/item-chat.png", text: "Kardex" },
    { img: "/item-chat.png", text: "Constancia" },
    { img: "/item-chat.png", text: "Titulacion" },
    { img: "/item-chat.png", text: "Creditos" },
    { img: "/item-chat.png", text: "Mas opciones..." },
  ];
  const additionalOptions = [
    { img: "/item-chat.png", text: "Historial Academico" },
    { img: "/item-chat.png", text: "Pagos y Finanzas" },
    { img: "/item-chat.png", text: "Horarios" },
  ];

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (showMap) document.body.classList.add("map-open");
    else document.body.classList.remove("map-open");
  }, [showMap]);

  // ================== Funciones ==================
  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  // Maneja clic en opciones de procesos administrativos
  const handleOptionClick = (option) => {
    const userMessage = { type: "user", content: option, timestamp: new Date() };

    if (option === "Mas opciones...") {
      setShowMoreOptions(true);
      setMessages((prev) => [
        ...prev,
        userMessage,
        { type: "bot", content: "moreOptions", timestamp: new Date() },
        {
          type: "bot",
          content:
            "Si no se encuentra la opción que busca, escríbala en el chat.",
          timestamp: new Date(),
        },
      ]);
      return;
    }

    const botInfo = {
      type: "bot",
      content: `Para el proceso de ${option.toLowerCase()} se tiene que hacer lo siguiente:

1.- Ingresa al SIM con tu número de control y contraseña.
2.- Dirígete al módulo correspondiente.
3.- Selecciona la opción necesaria.
4.- Sigue las instrucciones mostradas.`,
      timestamp: new Date(),
    };

    const botActions = {
      type: "bot",
      content:
        'Si quiere cambiar de proceso, puede elegir otra opción o escribir su consulta.',
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage, botInfo, botActions]);
  };

  // Genera respuesta automática según el texto del usuario
  const handleSendMessage = () => {
    if (!inputValue.trim()) return;

    const userMessage = { type: "user", content: inputValue, timestamp: new Date() };
    const input = inputValue.toLowerCase();
    let botResponse = { type: "bot", content: "", timestamp: new Date() };
    let extraResponses = [];

    // ================== Procesos administrativos ==================
    if (input.includes("kardex")) botResponse.content = `El Kardex muestra tu historial académico completo.`;
    else if (input.includes("constancia")) botResponse.content = `La constancia de estudios se solicita en servicios escolares.`;
    else if (input.includes("titulacion")) botResponse.content = `El proceso de titulación implica completar créditos y requisitos.`;
    else if (input.includes("credito")) botResponse.content = `Los créditos complementarios se registran en actividades culturales o académicas.`;
    else if (input.includes("historial")) botResponse.content = `El historial académico se descarga desde el portal del SIM.`;
    else if (input.includes("pago")) botResponse.content = `Los pagos se realizan en caja o por transferencia.`;
    else if (input.includes("horario")) botResponse.content = `Tu horario actual se encuentra en el portal del SIM.`;

    // ================== Ubicaciones ==================
    else {
      const ubicacion = ubicacionesData.find((u) => u.id === inputValue.toUpperCase());
      if (ubicacion) {
        botResponse.content = ubicacion.texto;
        extraResponses.push({ type: "bot", content: "building_image", buildingImage: ubicacion.imagen });
        extraResponses.push({ type: "bot", content: "Si desea saber otra ubicación, escríbala o use el mapa." });
      } else {
        botResponse.content = `Has escrito: "${inputValue}". Por favor, proporciona más detalles o selecciona una opción.`;
      }
    }

    setMessages((prev) => [...prev, userMessage, botResponse, ...extraResponses]);
    setInputValue("");
  };

  const toggleMap = () => {
    if (showMap) {
      setAnimateMap(false);
      setTimeout(() => setShowMap(false), 300);
    } else {
      setShowMap(true);
      setTimeout(() => setAnimateMap(true), 10);
    }
  };

  const handleMapButtonClick = (id) => {
    const ubicacion = ubicacionesData.find((u) => u.id === id);
    if (!ubicacion) return;
    const userMessage = { type: "user", content: id };
    const botResponses = [
      { type: "bot", content: ubicacion.texto },
      { type: "bot", content: "building_image", buildingImage: ubicacion.imagen },
    ];
    setMessages((prev) => [...prev, userMessage, ...botResponses]);
  };

  // ================== Render ==================
  return (
    <div className="fusion-container">
      <header className="fusion-header">
        <div className="fusion-header-left">
          <button className="fusion-back-button" onClick={() => navigate("/")}>
            <i className="bi bi-chevron-double-left"></i>
          </button>
          <h1>TalkinPon</h1>
        </div>
        <div className="fusion-title">
          <h2>Procesos y Ubicaciones</h2>
        </div>
        <div className="fusion-logo">
          <button onClick={toggleMap} className="fusion-toggle-map">
            <i className="bi bi-map-fill"></i>
          </button>
          <img src="/logo-app.png" alt="Logo" />
        </div>
      </header>

      <div className="fusion-chat-area">
        {messages.map((message, idx) => (
          <div key={idx} className={`fusion-chat-message ${message.type}`}>
            <div className="fusion-avatar">
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "Usuario"}
              />
            </div>
            <div className="fusion-message-content">
              {message.content === "options" || message.content === "moreOptions" ? (
                <div className="fusion-options-box">
                  <h3>{message.content === "options" ? "Elige una opción:" : "Más opciones:"}</h3>
                  {(message.content === "options" ? predefinedOptions : additionalOptions).map((option, i) => (
                    <button key={i} onClick={() => handleOptionClick(option.text)}>
                      <img src={option.img} alt={option.text} />
                      <span>{option.text}</span>
                    </button>
                  ))}
                </div>
              ) : message.content === "building_image" ? (
                <img src={message.buildingImage} alt="Edificio" className="fusion-building-image" />
              ) : (
                <p>{message.content}</p>
              )}
            </div>
          </div>
        ))}
        <div ref={chatEndRef}></div>
      </div>

      <div className="fusion-input-area">
        <input
          type="text"
          placeholder="¿Qué te gustaría saber ...?"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={handleKeyPress}
        />
        <button onClick={handleSendMessage}>
          <i className="bi bi-send-fill"></i>
        </button>
      </div>

      {/* Mapa */}
      {showMap && (
        <>
          <div className="map-overlay"></div>
          <div className={`map-area ${animateMap ? "map-open" : "map-close"}`}>
            <div className="map-header">
              <h3>Mapa del Campus</h3>
              <button
                onClick={() => {
                  setAnimateMap(false);
                  setTimeout(() => setShowMap(false), 300);
                }}
                className="close-map-btn"
              >
                ✕
              </button>
            </div>
            <div className="map-container">
              <img src="/mapa_tec.png" alt="Mapa Campus" className="campus-map" />
              {ubicacionesData.map((u) => (
                <button
                  key={u.id}
                  className="map-button"
                  style={{ top: u.posicionMapa.top, left: u.posicionMapa.left }}
                  onClick={() => handleMapButtonClick(u.id)}
                >
                  {u.id}
                </button>
              ))}
            </div>
            <p className="map-caption">Mapa interactivo del campus universitario</p>
          </div>
        </>
      )}
    </div>
  );
}
